const LetterBadge: React.FC<{ k: string }> = ({ k }) => {
  const map: Record<string, { t: string; bg: string; fg: string }> = {
    '@pr': { t: 'Pr', bg: '#00005B', fg: '#9999FF' },
    '@ps': { t: 'Ps', bg: '#001E36', fg: '#31A8FF' },
    '@ca': { t: 'Ca', bg: 'linear-gradient(135deg,#00C4CC,#7D2AE8)', fg: '#ffffff' },
  };
  const m = map[k];
  return (
    <span
      className="grid place-items-center w-9 h-9 rounded-lg font-extrabold text-[15px] tracking-tight"
      style={{ background: m.bg, color: m.fg }}
    >
      {m.t}
    </span>
  );
};

const ToolTile: React.FC<{ tool: Tool }> = ({ tool }) => {
  const icon = ICONS[tool.key];
  const color = tool.key === '@pr' ? '#9999FF' : tool.key === '@ps' ? '#31A8FF' : tool.key === '@ca' ? '#7D2AE8' : icon?.h ?? '#3B82F6';
  return (
    <div className="tool-tile group" style={{ ['--c' as string]: color }} title={tool.label}>
      <div className="tool-icon">
        {icon ? (
          <svg viewBox="0 0 24 24" width="34" height="34" role="img" aria-label={tool.label} fill={icon.h === '#FFFFFF' ? '#0F2A5F' : icon.h}>
            <path d={icon.p} />
          </svg>
        ) : (
          <LetterBadge k={tool.key} />
        )}
      </div>
      <span className="tool-label">{tool.label}</span>
    </div>
  );
};

